#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Detections;
using MVZ2.GameContent.Models;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Models;
using MVZ2Logic.Models;
using PVZEngine.Buffs;
using PVZEngine.Collisions;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Tools;

namespace MVZ2.GameContent.Buffs.Projectiles
{
    [AutoBuffDefinition(VanillaBuffNames.Projectile.prismPylonProjectileCyan)]
    public class PrismPylonProjectileCyanBuff : BuffDefinition
    {
        public PrismPylonProjectileCyanBuff(string nsp, string name) : base(nsp, name)
        {
            AddModelInsertion(LogicModelHelper.ANCHOR_CENTER, VanillaModelKeys.dazzle, VanillaModelID.dazzle);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var entity = buff.GetEntity();
            if (entity == null)
                return;
            if (!entity.IsTimeInterval(4))
                return;
            using var bufferItem = ListPool<IEntityCollider>.Rent();
            var buffer = bufferItem.Value;
            detector.DetectMultiple(entity, buffer);
            var effects = new DamageEffectList(VanillaDamageEffects.LIGHT, VanillaDamageEffects.MUTE);
            foreach (var collider in buffer)
            {
                collider.TakeDamage(entity.GetDamage() * DAMAGE_MULTIPLIER, effects, entity);
            }
        }
        public const float RADIUS = 80f;
        public const float DAMAGE_MULTIPLIER = 0.2f;
        private static Detector detector = new SphereDetector(RADIUS)
        {
            canDetectInvisible = true,
        };
    }
}
